"use client";

import * as React from "react";
import { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<Props> = Omit<Props, "className"> & { className?: string };

type PositionerProps = Pick<
  ContextMenuPrimitive.Positioner.Props,
  "align" | "alignOffset" | "side" | "sideOffset"
>;

/** The menu panel: the white card with the olive hairline, at least 12rem wide. */
const menuPanel = cn(
  popoverSurface,
  popupMotion,
  "min-w-48 max-h-(--available-height) overflow-y-auto p-1",
);

/** Playful console ContextMenu root: a menu of actions on a right click or long press. */
const ContextMenu = ContextMenuPrimitive.Root;

/** The area that opens the menu on a right click or long press. */
const ContextMenuTrigger = ContextMenuPrimitive.Trigger;

/** Groups related rows, and gives a label something to name. */
const ContextMenuGroup = ContextMenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const ContextMenuPortal = ContextMenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const ContextMenuSub = ContextMenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const ContextMenuRadioGroup = ContextMenuPrimitive.RadioGroup;

/**
 * The context menu panel: a white card with the olive hairline and a soft
 * drop. It opens at the pointer and grows from that point.
 */
function ContextMenuContent({
  className,
  ...props
}: WithClassName<ContextMenuPrimitive.Popup.Props>) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner className="isolate z-50 outline-none">
        <ContextMenuPrimitive.Popup
          data-slot="context-menu-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuContent.displayName = "ContextMenuContent";

/** A nested menu panel. It opens beside its row, level with the row's top. */
function ContextMenuSubContent({
  className,
  align = "start",
  alignOffset = -4,
  side = "right",
  sideOffset = 2,
  ...props
}: WithClassName<ContextMenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <ContextMenuPrimitive.Popup
          data-slot="context-menu-sub-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuSubContent.displayName = "ContextMenuSubContent";

/**
 * A menu row with a 0.25rem corner that takes a cream wash under the pointer
 * or keyboard. The destructive variant turns the text red on a red tint.
 */
function ContextMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: WithClassName<ContextMenuPrimitive.Item.Props> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <ContextMenuPrimitive.Item
      data-slot="context-menu-item"
      data-variant={variant}
      className={cn(
        menuItemBase,
        "[&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground",
        variant === "destructive" &&
          "text-(--destructive-text) data-[highlighted]:bg-(--destructive-tint) data-[highlighted]:text-(--destructive-text) [&_svg]:text-(--destructive-text)",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
ContextMenuItem.displayName = "ContextMenuItem";

/** A row that opens a nested menu, with a caret at the end. */
function ContextMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.SubmenuTrigger.Props> & {
  inset?: boolean;
}) {
  return (
    <ContextMenuPrimitive.SubmenuTrigger
      data-slot="context-menu-sub-trigger"
      className={cn(
        menuItemBase,
        "data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      <Icon
        icon="ph:caret-right-bold"
        className="ms-auto size-3.5 text-muted-foreground rtl:rotate-180"
        aria-hidden="true"
      />
    </ContextMenuPrimitive.SubmenuTrigger>
  );
}
ContextMenuSubTrigger.displayName = "ContextMenuSubTrigger";

/** A row that toggles on and off. A small orange key with a tick sits at the end when on. */
function ContextMenuCheckboxItem({
  className,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.CheckboxItem.Props>) {
  return (
    <ContextMenuPrimitive.CheckboxItem
      data-slot="context-menu-checkbox-item"
      className={cn(menuItemBase, "pe-8", className)}
      {...props}
    >
      {children}
      <span className="pointer-events-none absolute end-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.CheckboxItemIndicator className="flex size-4 items-center justify-center rounded-md border border-(--primary-rim) bg-primary text-primary-foreground">
          <Icon icon="ph:check-bold" className="size-2.5" aria-hidden="true" />
        </ContextMenuPrimitive.CheckboxItemIndicator>
      </span>
    </ContextMenuPrimitive.CheckboxItem>
  );
}
ContextMenuCheckboxItem.displayName = "ContextMenuCheckboxItem";

/** One choice in a radio group. An orange dot with its rim sits at the end when chosen. */
function ContextMenuRadioItem({
  className,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.RadioItem.Props>) {
  return (
    <ContextMenuPrimitive.RadioItem
      data-slot="context-menu-radio-item"
      className={cn(menuItemBase, "pe-8", className)}
      {...props}
    >
      {children}
      <span className="pointer-events-none absolute end-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.RadioItemIndicator>
          <span className="block size-2.5 rounded-full border border-(--primary-rim) bg-primary" />
        </ContextMenuPrimitive.RadioItemIndicator>
      </span>
    </ContextMenuPrimitive.RadioItem>
  );
}
ContextMenuRadioItem.displayName = "ContextMenuRadioItem";

/** A small bold uppercase heading over a group of rows. Use it inside a group. */
function ContextMenuLabel({
  className,
  inset,
  ...props
}: WithClassName<ContextMenuPrimitive.GroupLabel.Props> & {
  inset?: boolean;
}) {
  return (
    <ContextMenuPrimitive.GroupLabel
      data-slot="context-menu-label"
      className={cn(
        "px-2.5 py-1.5 text-xs font-bold uppercase text-muted-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
ContextMenuLabel.displayName = "ContextMenuLabel";

/** A soft line between groups that runs to the panel's edges. */
function ContextMenuSeparator({
  className,
  ...props
}: WithClassName<ContextMenuPrimitive.Separator.Props>) {
  return (
    <ContextMenuPrimitive.Separator
      data-slot="context-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-(--line-soft)", className)}
      {...props}
    />
  );
}
ContextMenuSeparator.displayName = "ContextMenuSeparator";

/** The keyboard shortcut at the end of a row, in small mono type. */
function ContextMenuShortcut({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      data-slot="context-menu-shortcut"
      className={cn("ms-auto ps-4 font-mono text-xs text-muted-foreground", className)}
      {...props}
    />
  );
}
ContextMenuShortcut.displayName = "ContextMenuShortcut";

export {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuCheckboxItem,
  ContextMenuRadioItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuGroup,
  ContextMenuPortal,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  ContextMenuRadioGroup,
};
